 y={'identifier':'kgmicrobe.ingredient:'+slug,'preferred_term':label,'mapping_status':'MAPPED','ingredient_type':'STOCK_SOLUTION','solution_type':'MINERAL_STOCK','synonyms':[{'synonym_text':A[i]['source']['raw_source_label'],'synonym_type':'REJECTED_LABEL','source':A[i]['source']['source_case_id']+'; bare source ingredient name lacks concentration and source qualification'}],'occurrence_statistics':{'total_occurrences':0,'media_count':0}}
